{
  "category_edits": [
    {
      "category": "learning_objective",
      "rationale": "Replace pairwise softplus with equally weighted positive and negative binary logistic losses to constrain absolute logits and potentially reduce score drift. Preserve valid-position averaging, sampled pairs, HSTU architecture, inference, optimizer and training schedule.",
      "edits": [
        {
          "find": "            loss = F.softplus(-(pos_scores - neg_scores))",
          "replace": "            loss = F.softplus(-pos_scores) + F.softplus(neg_scores)"
        }
      ]
    }
  ],
  "change_summary": "Change only the training objective to positive-plus-negative binary logistic loss for all four category models. Predictor and checkpoint formats remain compatible."
}
